CREATE COLUMN TABLE "TEST_AP"."OCOG" ("GroupCode" SMALLINT CS_INT NOT NULL , "GroupName" NVARCHAR(30) NOT NULL , "Commission" DECIMAL(21,6) CS_FIXED, "PrvComsnPr" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("GroupCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCOG_GROUP_NAME" ON "TEST_AP"."OCOG" ( "GroupName" ASC )